        emon.Testport.assertEq(Asset.asGet(cand, 0, 9), Model.nzPart(), "its status is part");
        atFigAt(nodes, regions, Model.nkFigure(), Model.fgUnknown(), 1, 10000, 10000, 20000, 20000);
