    public static int atNl(byte[] b, int i) {
        int k = i;
        while ((k < emon.Port.blobLen(b)) && (emon.Port.blobU8(b, k) != 10)) {
            k += 1;
        }
        return k;
    }
    public static int atSep(byte[] b, int i, int lim, int ch) {
        // Index of the next `ch` in [i, lim), or lim.
        int k = i;
        while ((k < lim) && (emon.Port.blobU8(b, k) != ch)) {
            k += 1;
        }
        return k;
    }
    public static int atField(byte[] b, int pos, int e, int n) {
        // Where the n-th tab-separated field of the row [pos, e) starts.
        int p = pos;
        int k = 0;
        while (k < n) {
            p = atSep(b, p, e, 9) + 1;
            k += 1;
        }
        return p;
    }
    public static int atInt(byte[] b, int from, int to) {
        int k = from;
        int v = 0;
        while (k < to) {
            v = (v * 10) + (emon.Port.blobU8(b, k) - 48);
            k += 1;
        }
        return v;
    }
    public static int atCint(byte[] b, int from, int to, int n) {
        // The n-th colon-separated integer of b[from, to).
        int p = from;
        int k = 0;
        while (k < n) {
            p = atSep(b, p, to, 58) + 1;
            k += 1;
        }
        return atInt(b, p, atSep(b, p, to, 58));
    }
    public static int atWord(emon.Port.Cells tmp, int i) {
        return (int) ((((long) emon.Port.cellsAt(tmp, i * 4)) * ((long) 16777216)) + ((long) ((emon.Port.cellsAt(tmp, (i * 4) + 1) * 65536) + ((emon.Port.cellsAt(tmp, (i * 4) + 2) * 256) + emon.Port.cellsAt(tmp, (i * 4) + 3)))));
    }
    public static int atRun(emon.Port.Src src, emon.Port.Cells cand, emon.Port.Buf cbytes, emon.Port.Cells pages, emon.Port.Cells fg, emon.Port.Cells im) {
        // Open the document, run its pages, collect its asset candidates into `cand` and `cbytes`, and find the provisional
        // figures into `fg` (pages are the Model's). Answers 0, or the failing step.
        emon.Port.Cells ar = emon.Port.newCells();
        emon.Port.Cells dc = emon.Port.newCells();
        emon.Port.Cells a = emon.Port.newCells();
        emon.Port.Cells b = emon.Port.newCells();
        emon.Port.Cells st = emon.Port.newCells();
        emon.Port.Cells cx = emon.Port.newCells();
        emon.Port.Cells ox = emon.Port.newCells();
        emon.Port.Cells cs = emon.Port.newCells();
        emon.Port.Cells out = emon.Port.newCells();
        emon.Port.Cells f0 = emon.Port.newCells();
        emon.Port.Cells f1 = emon.Port.newCells();
        emon.Port.Cells f2 = emon.Port.newCells();
        emon.Port.Cells f3 = emon.Port.newCells();
        emon.Port.Cells gl = emon.Port.newCells();
        emon.Port.Cells et = emon.Port.newCells();
        emon.Port.Cells mk = emon.Port.newCells();
        emon.Port.Cells fnt = emon.Port.newCells();
        emon.Port.Cells pg = emon.Port.newCells();
        emon.Port.Cells wd = emon.Port.newCells();
        emon.Port.Cells ln = emon.Port.newCells();
        emon.Port.Cells pa = emon.Port.newCells();
        emon.Port.Cells pts = emon.Port.newCells();
        emon.Port.Cells gx = emon.Port.newCells();
        emon.Port.Cells o2 = emon.Port.newCells();
        emon.Port.Cells rec = emon.Port.newCells();
        emon.Port.Cells mrec = emon.Port.newCells();
        emon.Port.Cells smp = emon.Port.newCells();
        emon.Port.Cells msmp = emon.Port.newCells();
        emon.Port.Cells data = emon.Port.newCells();
        emon.Port.Cells rows = emon.Port.newCells();
        emon.Port.Cells tmp = emon.Port.newCells();
        emon.Port.Cells ws = emon.Port.newCells();
        emon.Port.Buf z = emon.Port.newBuf();
        if (Pdfdoc.pdOpen(src, ar, dc, a, b, st) != 0) {
            return 1;
        }
        if (Pdfcontent.pcDocument(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln, pa, im, pts, gx) != 0) {
            return 2;
        }
        if (Asset.asCollect(src, ar, dc, a, b, st, im, pa, gl, pg, 4194304, 33554432, 1, emon.Port.newCells(), cand, cbytes, o2, rec, mrec, smp, msmp, data, rows, tmp, ws, z) != 0) {
            return 3;
        }
        Para.paPages(pg, pages);
        Asset.asFigureRows(cand, pages, emon.Port.newCells(), emon.Port.newCells(), 1, fg);
        return 0;
    }
    public static int atCandsRow(int emonT, byte[] rows, int pos, int e, int line) {
        // file n cand...: each candidate status:type:origin:from:w:h:flags, in the order of the provisional figures
        emon.Port.Cells cand = emon.Port.newCells();
        emon.Port.Cells pages = emon.Port.newCells();
        emon.Port.Cells fg = emon.Port.newCells();
        emon.Port.Cells im = emon.Port.newCells();
        emon.Port.Cells tmp = emon.Port.newCells();
        emon.Port.Buf cbytes = emon.Port.newBuf();
        int fs = atField(rows, pos, e, 0);
        int fe = atSep(rows, fs, e, 9);
        int ns = atField(rows, pos, e, 1);
        int n = atInt(rows, ns, atSep(rows, ns, e, 9));
        int k = 0;
        int r = 0;
        int p = 0;
        int q = 0;
        int i = 0;
        emon.Testport.assertEqAt(atRun(emon.Port.srcOfBlob(emon.Testport.testFileSpan(rows, fs, fe)), cand, cbytes, pages, fg, im), 0, "the document runs", line);
        emon.Testport.assertEqAt(emon.Port.cellsLen(fg), n + 1, "the provisional figures", line);
        if (emon.Port.cellsLen(fg) == (n + 1)) {
            while (k < n) {
                r = emon.Port.cellsAt(fg, k + 1);
                p = atField(rows, pos, e, 2 + k);
                q = atSep(rows, p, e, 9);
                emon.Testport.assertEqAt(Asset.asGet(cand, r, 9), atCint(rows, p, q, 0), "the status", line);
                if (atCint(rows, p, q, 0) == 0) {
                    emon.Testport.assertEqAt(Asset.asGet(cand, r, 10), atCint(rows, p, q, 1), "the media type", line);
                    emon.Testport.assertEqAt(Asset.asGet(cand, r, 26), atCint(rows, p, q, 2), "the origin", line);
                    emon.Testport.assertEqAt(Asset.asGet(cand, r, 24), atCint(rows, p, q, 3), "from", line);
                    emon.Testport.assertEqAt(Asset.asGet(cand, r, 21), atCint(rows, p, q, 4), "the width", line);
                    emon.Testport.assertEqAt(Asset.asGet(cand, r, 22), atCint(rows, p, q, 5), "the height", line);
                    emon.Testport.assertEqAt(Asset.asGet(cand, r, 23), atCint(rows, p, q, 6), "the flags", line);
                    // the bytes hash to the row's SHA-256, and a JPEG is a JPEG, a PNG a PNG
                    emon.Port.cellsDrop(tmp, 0);
                    emon.Port.cryptoSha256(emon.Port.bufBlob(cbytes), Asset.asGet(cand, r, 11), Asset.asGet(cand, r, 12), tmp);
                    i = 0;
                    while (i < 8) {
                        emon.Testport.assertEqAt(Asset.asGet(cand, r, 13 + i), atWord(tmp, i), "the SHA-256 word", line);
                        i += 1;
                    }
                    if (atCint(rows, p, q, 1) == 1) {
                        emon.Testport.assertEqAt(emon.Port.bufAt(cbytes, Asset.asGet(cand, r, 11)), 255, "SOI", line);
                        emon.Testport.assertEqAt(emon.Port.bufAt(cbytes, Asset.asGet(cand, r, 11) + 1), 216, "SOI", line);
                        emon.Testport.assertEqAt(emon.Port.bufAt(cbytes, (Asset.asGet(cand, r, 11) + Asset.asGet(cand, r, 12)) - 2), 255, "EOI", line);
                        emon.Testport.assertEqAt(emon.Port.bufAt(cbytes, (Asset.asGet(cand, r, 11) + Asset.asGet(cand, r, 12)) - 1), 217, "EOI", line);
                    }
                    if (atCint(rows, p, q, 1) == 2) {
                        emon.Testport.assertEqAt(emon.Port.bufAt(cbytes, Asset.asGet(cand, r, 11)), 137, "PNG signature", line);
                        emon.Testport.assertEqAt(emon.Port.bufAt(cbytes, Asset.asGet(cand, r, 11) + 1), 80, "PNG signature", line);
                    }
                }
                k += 1;
            }
        }
        return 0;
    }
    public static void testTheFixturesMakeTheirCandidates() {
        byte[] rows = emon.Testport.testFile("asset/cands.txt");
        int n = emon.Port.blobLen(rows);
        int pos = 0;
        int line = 0;
        int e = 0;
        int checked = 0;
        while (pos < n) {
            line += 1;
            e = atNl(rows, pos);
            if ((pos < e) && (emon.Port.blobU8(rows, pos) != 35)) {
                atCandsRow(0, rows, pos, e, line);
                checked += 1;
            }
            pos = e + 1;
        }
        emon.Testport.assertThat(checked > 60, "every file of test/asset/cands.txt is checked");
    }
    public static int atOri(int emonT, byte[] file, int want, int line) {
        emon.Port.Cells cand = emon.Port.newCells();
        emon.Port.Cells pages = emon.Port.newCells();
        emon.Port.Cells fg = emon.Port.newCells();
        emon.Port.Cells im = emon.Port.newCells();
        emon.Port.Buf cbytes = emon.Port.newBuf();
        emon.Testport.assertEqAt(atRun(emon.Port.srcOfBlob(file), cand, cbytes, pages, fg, im), 0, "the document runs", line);
        emon.Testport.assertEqAt(Evidence.imCount(im), 1, "one placement", line);
        emon.Testport.assertEqAt(Evidence.imGet(im, 0, Evidence.mfPlacement()), want, "the placement's orientation", line);
        return 0;
    }
    public static void testAPlacementRecordsItsOrientationAsThePageShowsIt() {
        // P3.12's O rows: the matrix of each place-* file and its code; -1 (not rectilinear) is recorded as 8
        atOri(0, emon.Testport.testFile("assets/place-upright.pdf"), 0, 1);
        atOri(0, emon.Testport.testFile("assets/place-rot90.pdf"), 5, 2);
        atOri(0, emon.Testport.testFile("assets/place-rot90cw.pdf"), 4, 3);
        atOri(0, emon.Testport.testFile("assets/place-rot180.pdf"), 2, 4);
        atOri(0, emon.Testport.testFile("assets/place-flip-h.pdf"), 1, 5);
        atOri(0, emon.Testport.testFile("assets/place-flip-v.pdf"), 3, 6);
        atOri(0, emon.Testport.testFile("assets/place-transpose.pdf"), 6, 7);
        atOri(0, emon.Testport.testFile("assets/place-antitranspose.pdf"), 7, 8);
        atOri(0, emon.Testport.testFile("assets/place-skew.pdf"), 8, 9);
    }
